// Writes lib/src/registry.g.dart, the registry that apps compile in, from server/crates/photolib-models/registry.json:
// dart run tool/registry.dart
import 'dart:io';

void main() => File('lib/src/registry.g.dart').writeAsStringSync(source());

/// The Dart source that holds the registry's JSON as it is.
String source() {
  final json = File('../../../server/crates/photolib-models/registry.json')
      .readAsStringSync();
  return '// Generated by tool/registry.dart from '
      'server/crates/photolib-models/registry.json; do not edit.\n'
      '// Raw, so that the JSON is kept byte for byte.\n'
      '// ignore_for_file: unnecessary_raw_strings\n\n'
      '/// registry.json.\n'
      "const registryJson = r'''\n$json''';\n";
}
